package com.aistock.prediction.marketuse;
import com.aistock.common.BusinessException;
import com.fasterxml.jackson.databind.*;
import com.sun.net.httpserver.HttpServer;
import java.net.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class MarketUseClientTest {
 final ObjectMapper m=new ObjectMapper();final String op=UUID.randomUUID().toString(),requestId=UUID.randomUUID().toString(),raw=UUID.randomUUID().toString(),bundle=UUID.randomUUID().toString(),use=UUID.randomUUID().toString();
 HttpServer server;String response;int status=200;AtomicInteger calls=new AtomicInteger();String path,body;
 MarketUseClient.Request request(){return new MarketUseClient.Request(op,"1",requestId,raw);}
 String receipt(String id,String state)throws Exception{var n=m.createObjectNode().put("protocolVersion","market-version-use-v1").put("bundleId",bundle).put("owner","prediction").put("purpose","STOCK_ANALYSIS").put("ownerOperationId",op).put("generation","1").put("state",state);if(id==null)n.putNull("requestId");else n.put("requestId",id);n.putArray("versionIds").add(raw);n.putArray("uses").addObject().put("useId",use).put("versionId",raw).put("lifecycleRevision","0");return m.createObjectNode().put("code","OK").set("data",n).toString();}
 @BeforeEach void setup()throws Exception{server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{calls.incrementAndGet();assertEquals("private",e.getRequestHeaders().getFirst("X-Service-Token"));path=e.getRequestURI().toString();body=new String(e.getRequestBody().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);byte[] bytes=response.getBytes(java.nio.charset.StandardCharsets.UTF_8);e.sendResponseHeaders(status,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();}
 @AfterEach void close(){server.stop(0);}
 MarketUseClient client(){return new MarketUseClient("http://127.0.0.1:"+server.getAddress().getPort(),"private",Duration.ofSeconds(1));}
 @Test void readinessRequiresActualEvidenceGateAndProtocol(){response="{\"code\":\"OK\",\"data\":{\"protocolVersion\":\"market-version-use-v1\",\"protocolEnabled\":true,\"evidenceGatesEnabled\":false}}";assertThrows(BusinessException.class,()->client().requireReady());response=response.replace("false","true");assertDoesNotThrow(()->client().requireReady());assertEquals("/internal/v1/market-version-uses/capabilities",path);}
 @Test void registerAndLookupBindExactIdentityAndManifest()throws Exception{response=receipt(requestId,"ACTIVE");var c=client();assertEquals(List.of(raw),c.register(request()).versionIds());var sent=m.readTree(body);assertEquals(requestId,sent.path("requestId").asText());assertEquals(raw,sent.path("selector").path("versionIds").get(0).asText());assertEquals(bundle,c.find(request()).orElseThrow().bundleId());assertTrue(path.startsWith("/internal/v1/market-version-uses/requests/"+requestId+"?"));response=response.replace(raw,UUID.randomUUID().toString());assertThrows(BusinessException.class,()->c.find(request()));}
 @Test void malformedDuplicateRedirectAndOversizedResponsesAreRejected()throws Exception{var c=client();response=receipt(requestId,"ACTIVE").replace("\"generation\":\"1\"","\"generation\":\"1\",\"generation\":\"2\"");assertThrows(BusinessException.class,()->c.register(request()));response=receipt(requestId,"ACTIVE");status=302;assertThrows(BusinessException.class,()->c.register(request()));status=200;response="x".repeat(65537);assertThrows(BusinessException.class,()->c.register(request()));}
 @Test void completionOnlySendsIdentityAndRequiresReleasedReceipt()throws Exception{var c=client();response=receipt(null,"RELEASED");var r=new MarketUseClient.Receipt(bundle,"ACTIVE",List.of(raw));assertEquals("RELEASED",c.complete(request(),r).state());assertEquals(Set.of("owner","purpose","ownerOperationId","generation"),m.convertValue(m.readTree(body),Map.class).keySet());response=receipt(null,"ACTIVE");assertThrows(BusinessException.class,()->c.complete(request(),r));}
 @Test void missingLookupIsNotPermissionToRegisterAgain(){response="{\"code\":\"MARKET_VERSION_RESOURCE_NOT_FOUND\",\"data\":null}";status=404;assertTrue(client().find(request()).isEmpty());assertEquals(1,calls.get());}
 @Test void invalidConfigurationAndMissingTokenDoNotSend(){response="{}";assertThrows(IllegalArgumentException.class,()->new MarketUseClient("http://x/path","private",Duration.ofSeconds(1)));assertThrows(IllegalArgumentException.class,()->new MarketUseClient("http://x","private",Duration.ofSeconds(5)));assertThrows(BusinessException.class,()->new MarketUseClient("http://127.0.0.1:"+server.getAddress().getPort(),"",Duration.ofSeconds(1)).requireReady());assertEquals(0,calls.get());}

 @Test void entireBodyHasDeadlineEvenAfterHeadersArrive()throws Exception{server.removeContext("/");var finish=new java.util.concurrent.CountDownLatch(1);server.createContext("/",e->{try{e.sendResponseHeaders(200,100);e.getResponseBody().write('{');e.getResponseBody().flush();finish.await(2,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception ignored){}finally{e.close();}});var c=new MarketUseClient("http://127.0.0.1:"+server.getAddress().getPort(),"private",Duration.ofMillis(150));try{assertTimeoutPreemptively(Duration.ofSeconds(1),()->assertThrows(BusinessException.class,c::requireReady));}finally{finish.countDown();}}

 @Test void forecastAndVerificationCanFreezeOneCurrentHeadAndKeepPurposeInLookup()throws Exception{for(String purpose:List.of("FORECAST","PREDICTION_VERIFICATION")){var selected=new com.aistock.common.marketlifecycle.MarketUseRecords.Selector("CURRENT_HEADS",null,null,List.of("SH600030"));var r=new MarketUseClient.Request(op,"1",requestId,purpose,selected);response=receipt(requestId,"ACTIVE").replace("STOCK_ANALYSIS",purpose);var found=client().register(r);assertEquals(raw,found.versionIds().get(0));assertEquals("CURRENT_HEADS",m.readTree(body).path("selector").path("kind").asText());client().find(r);assertTrue(path.contains("purpose="+purpose));try(var scope=MarketUseContext.open(r,found)){assertEquals(purpose,MarketUseContext.headers().get("X-Market-Use-Purpose"));}}}

 @Test void comparisonBindsExactMultipleVersionsAndRejectsDuplicateUseOrMissingMember()throws Exception{String other=UUID.randomUUID().toString();var selected=new com.aistock.common.marketlifecycle.MarketUseRecords.Selector("COMPARISON_EVIDENCE",null,List.of(new com.aistock.common.marketlifecycle.MarketUseRecords.EvidenceBinding("SH600030",UUID.randomUUID().toString()),new com.aistock.common.marketlifecycle.MarketUseRecords.EvidenceBinding("SH600276",UUID.randomUUID().toString())),null);var r=new MarketUseClient.Request(op,"1",requestId,"COMPARISON",selected);var data=(com.fasterxml.jackson.databind.node.ObjectNode)m.readTree(receipt(requestId,"ACTIVE")).path("data");data.put("purpose","COMPARISON");data.withArray("versionIds").add(other);data.withArray("uses").addObject().put("useId",UUID.randomUUID().toString()).put("versionId",other).put("lifecycleRevision","2");response=m.createObjectNode().put("code","OK").set("data",data).toString();var found=client().register(r);try(var scope=MarketUseContext.open(r,found)){assertEquals(2,MarketUseContext.expectedVersions().size());assertNull(MarketUseContext.expectedRaw());}data.withArray("uses").get(1).deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)data.withArray("uses").get(1)).put("versionId",raw);response=m.createObjectNode().put("code","OK").set("data",data).toString();assertThrows(com.aistock.common.BusinessException.class,()->client().register(r));}
}
